<div class="admin-two-col admin-section-gap">
<section class="card"><h2>Log outreach</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="supplier_id" value="<?= $id ?>"><input type="hidden" name="action" value="outreach"><div class="form-grid">
<div class="field"><label>Channel</label><select name="channel"><option>Email</option><option>WhatsApp</option><option>Phone</option><option>Meeting</option><option>Other</option></select></div><div class="field"><label>Contacted at</label><input type="datetime-local" name="contacted_at" value="<?= e(date('Y-m-d\TH:i')) ?>"></div><div class="field full"><label>Subject</label><input name="subject" maxlength="180" placeholder="Wholesale / reseller enquiry"></div><div class="field"><label>Outcome</label><select name="outcome"><option>Awaiting response</option><option>Responded</option><option>Information requested</option><option>Terms received</option><option>Closed</option><option>Rejected</option></select></div><div class="field"><label>Next follow-up</label><input type="date" name="next_follow_up"></div><div class="field full"><label>Notes</label><textarea name="outreach_notes" required maxlength="10000"></textarea></div><div class="field full"><button class="btn primary">Add outreach entry</button></div></div></form></section>
<section class="card"><h2>Outreach history</h2><div class="timeline"><?php foreach($outreach as $o): ?><article><div><strong><?= e($o['channel']) ?> · <?= e($o['outcome']) ?></strong><small><?= e($o['contacted_at']) ?><?= $o['display_name'] ? ' · '.e($o['display_name']) : '' ?></small></div><?php if($o['subject']):?><p><?= e($o['subject']) ?></p><?php endif;?><p><?= nl2br(e($o['notes'])) ?></p><?php if($o['next_follow_up']):?><span class="tag">Follow up <?= e($o['next_follow_up']) ?></span><?php endif;?></article><?php endforeach;?><?php if(!$outreach):?><p class="muted">No outreach logged yet.</p><?php endif;?></div></section>
</div>
